import sys
import json
import zipfile
import hashlib
import base64
import io
import calendar


def is_valid_path(path):
    if not isinstance(path, str):
        return False
    if not path:
        return False
    if path.startswith('/'):
        return False
    if '\\' in path:
        return False
    parts = path.split('/')
    for part in parts:
        if part == '' or part == '.' or part == '..':
            return False
    return True


def is_valid_base64(s):
    if not isinstance(s, str):
        return False
    if len(s) % 4 != 0:
        return False
    for c in s:
        if c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=':
            return False
    # Validate padding: only 0, 1, or 2 trailing '='
    stripped = s.rstrip('=')
    if len(stripped) % 4 != 0:
        return False
    n = len(s) - len(stripped)
    if n > 2:
        return False
    try:
        base64.b64decode(s, validate=True)
        return True
    except Exception:
        return False


def validate_request(request):
    if not isinstance(request, dict):
        return False
    if set(request.keys()) != {"members", "timestamp", "comment"}:
        return False

    members = request["members"]
    if not isinstance(members, list):
        return False
    if not (1 <= len(members) <= 64):
        return False

    paths = []
    for member in members:
        if not isinstance(member, dict):
            return False
        if set(member.keys()) != {"path", "content_b64", "mode"}:
            return False

        path = member["path"]
        content_b64 = member["content_b64"]
        mode = member["mode"]

        if not is_valid_path(path):
            return False

        if not is_valid_base64(content_b64):
            return False
        content = base64.b64decode(content_b64, validate=True)
        if len(content) > 64 * 1024:
            return False

        if not isinstance(mode, int) or isinstance(mode, bool):
            return False
        if not (0 <= mode <= 511):
            return False

        paths.append(path)

    if len(set(paths)) != len(paths):
        return False

    timestamp = request["timestamp"]
    if not isinstance(timestamp, list) or len(timestamp) != 6:
        return False
    if not all(isinstance(t, int) and not isinstance(t, bool) for t in timestamp):
        return False

    year, month, day, hour, minute, second = timestamp
    if not (1980 <= year <= 2107):
        return False
    if not (1 <= month <= 12):
        return False
    if not (1 <= day <= calendar.monthrange(year, month)[1]):
        return False
    if not (0 <= hour <= 23):
        return False
    if not (0 <= minute <= 59):
        return False
    if not (0 <= second <= 59):
        return False
    if second % 2 != 0:
        return False

    comment = request["comment"]
    if not isinstance(comment, str) or len(comment) > 200:
        return False

    return True


def build_archive(request):
    buffer = io.BytesIO()

    members = sorted(request["members"], key=lambda m: m["path"])
    timestamp = request["timestamp"]
    year, month, day, hour, minute, second = timestamp

    # DOS date/time encoding for ZIP
    file_date = ((year - 1980) << 9) | (month << 5) | (day << 2)
    file_time = (hour << 11) | (minute << 5) | (second // 2)

    with zipfile.ZipFile(buffer, mode='w', compression=zipfile.ZIP_DEFLATED) as zf:
        zf.comment = request["comment"]

        for member in members:
            path = member["path"]
            content = base64.b64decode(member["content_b64"], validate=True)
            mode = member["mode"]

            info = zipfile.ZipInfo(path)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.file_date = file_date
            info.file_time = file_time
            info.external_attr = (0o100000 | mode) << 16

            zf.writestr(info, content)

    return buffer.getvalue()


def main():
    try:
        raw = sys.stdin.buffer.read()
        request = json.loads(raw.decode('utf-8'))
    except Exception:
        print(json.dumps({"error": "invalid_request"}, separators=(',', ':')))
        sys.exit(0)

    if not validate_request(request):
        print(json.dumps({"error": "invalid_request"}, separators=(',', ':')))
        sys.exit(0)

    archive_bytes = build_archive(request)
    archive_b64 = base64.b64encode(archive_bytes).decode('ascii')
    sha256 = hashlib.sha256(archive_bytes).hexdigest()

    result = {
        "format": "zip",
        "archive_b64": archive_b64,
        "sha256": sha256
    }
    print(json.dumps(result, separators=(',', ':')))


if __name__ == "__main__":
    main()
"}

